// Turns the chosen source into one Nilyo call. Nothing to edit here: everything comes from Settings.
const s = $('Set Workflow Parameters').first().json;
let tool, args;
if (s.source === 'saved_search') {
  tool = s.saved_search_tool;
  args = { load_saved_search: s.saved_search_id };
} else if (s.source === 'parameters') {
  tool = s.search_tool;
  try { args = JSON.parse(s.search_arguments || '{}'); }
  catch (e) { throw new Error('search_arguments in Settings is not valid JSON: ' + e.message); }
} else {
  tool = 'linkedin_search_from_url';
  args = { url: s.search_url, product: s.search_product };
}
return [{ json: { tool, args: JSON.stringify(args) } }];

// Keeps the people we can still invite, in search order.
// Search results expose id, display_name, headline and network_distance; there is no first_name field,
// so the first name is derived from display_name for the {first_name} placeholder.
const s = $('Set Workflow Parameters').first().json;
const pending = new Set(
  $('Check Pending Invitations').all()
    .map(i => i.json?.user?.id)
    .filter(Boolean)
    .map(String),
);
const seen = new Set();
const people = [];
for (const item of $input.all()) {
  const r = item.json || {};
  const id = r.id ? String(r.id) : '';
  if (!id || seen.has(id) || pending.has(id)) continue;      // no id, duplicate, or invitation already pending
  if (r.network_distance === 'FIRST_DEGREE' || r.network_distance === 'SELF') continue;  // already connected
  seen.add(id);
  const display = String(r.display_name || '').trim();
  people.push({
    user_id: id,
    display_name: display,
    first_name: display.split(' ')[0] || 'there',
    headline: r.headline || '',
    profile_url: r.profile_url || '',
  });
}
return people.slice(0, s.invitations_per_day).map(json => ({ json }));

// Renders the note for this person. An empty note in Settings means: invite without a note.
const s = $('Set Workflow Parameters').first().json;
const p = $json;
const note = String(s.invitation_note || '')
  .replaceAll('{first_name}', p.first_name)
  .replaceAll('{display_name}', p.display_name)
  .trim();
return [{ json: { ...p, note } }];

// Three outcomes, so the loop never retries a refusal:
//   sent            -> keep going
//   skipped         -> this person cannot be invited right now, next one
//   stop_for_today  -> a quota was hit, stop the run; tomorrow's schedule resumes
const r = $json || {};
const code = r.error?.code || r.code || null;
const skip = ['INVITATION_ALREADY_SENT', 'INVITATION_COOLDOWN'];
const stop = ['INVITATION_NOTE_QUOTA_REACHED', 'PROVIDER_ACTION_LIMIT', 'PROVIDER_RATE_LIMITED', 'PROVIDER_AUTHORIZATION_ERROR', 'SUBSCRIPTION_REQUIRED'];
const person = $('Compose Invitation Note').item.json;
return [{ json: {
  user_id: person.user_id,
  display_name: person.display_name,
  outcome: !code ? 'sent' : skip.includes(code) ? 'skipped' : stop.includes(code) ? 'stop_for_today' : 'failed',
  error_code: code,
} }];

// The people currently in the sequence: connections accepted inside the window.
// A relation is { id, user: {...}, created_at }; created_at is when the connection was accepted.
const s = $('Set Workflow Parameters').first().json;
const limit = Date.now() - s.sequence_window_days * 86400000;
const out = [];
for (const item of $input.all()) {
  const r = item.json || {};
  const user = r.user || {};
  if (!user.id) continue;
  const accepted = r.created_at ? new Date(r.created_at).getTime() : null;
  if (accepted && accepted < limit) continue;          // connected too long ago to be part of this sequence
  const display = String(user.display_name || [user.first_name, user.last_name].filter(Boolean).join(' ')).trim();
  out.push({ json: {
    user_id: String(user.id),
    display_name: display,
    first_name: user.first_name || display.split(' ')[0] || 'there',
    accepted_at: r.created_at || null,
  } });
}
return out;

// Decides what this person is owed today, reading the conversation itself.
// The number of messages you sent is the step index, so nothing can drift between runs,
// and one inbound message ends the sequence for good: the conversation becomes manual.
const s = $('Set Workflow Parameters').first().json;
const person = $('Batch Process Participants').item.json;
const chat = $('Locate Conversation Thread').item.json || {};
const chatId = chat.id && !chat.error ? String(chat.id) : '';

// Safety rules. A sequence that writes to strangers must fail closed, never open:
//  - a conversation we could not read is not an empty conversation: it blocks the run
//  - a message whose direction is unknown counts as theirs for stopping AND as ours for the step
//    index, so a missing is_sender can only ever hold the sequence back, never repeat a message
//  - a text already present in the conversation is never sent again, whatever the direction says
// An empty conversation is legitimate; a failed read is not, and the two must never be confused.
const raw = $input.all().map(i => i.json || {});
const messages = raw.filter(m => m && m.timestamp && !m.error);
if (raw.some(m => m && m.error)) {
  return [{ json: { action: 'skip_unreadable', user_id: person.user_id, display_name: person.display_name } }];
}
const normalize = t => String(t || '').replace(/\s+/g, ' ').trim().toLowerCase().slice(0, 160);
const alreadySaid = text => { const t = normalize(text); return t.length > 12 && messages.some(m => normalize(m.text).includes(t)); };

if (messages.some(m => m.is_sender !== true)) {
  return [{ json: { action: 'stop_replied', user_id: person.user_id, display_name: person.display_name } }];
}
const mine = messages
  .filter(m => m.is_sender !== false)
  .sort((a, b) => String(a.timestamp).localeCompare(String(b.timestamp)));

const noteWasSent = String(s.invitation_note || '').trim().length > 0;
const steps = [s.opening_message, s.follow_up_1, s.follow_up_2, s.follow_up_3];
// With a note on the invitation, the note took the place of the opening message: the sequence starts
// at follow-up 1, so every message you sent afterwards shifts the index by one.
const firstStep = noteWasSent ? 1 : 0;
const index = firstStep + mine.length;
if (index >= steps.length) return [{ json: { action: 'done', user_id: person.user_id } }];

// Only the opening message of a note-less invitation goes out immediately; everything else waits.
const sendsNow = !noteWasSent && mine.length === 0;
if (!sendsNow) {
  const since = mine.length
    ? new Date(mine[mine.length - 1].timestamp).getTime()
    : person.accepted_at ? new Date(person.accepted_at).getTime() : null;
  if (since === null) {
    return [{ json: { action: 'wait', user_id: person.user_id, reason: 'no acceptance date on this connection' } }];
  }
  const days = (Date.now() - since) / 86400000;
  if (days < s.days_between_messages) {
    return [{ json: { action: 'wait', user_id: person.user_id, display_name: person.display_name, days_since_last: Number(days.toFixed(1)) } }];
  }
}
const text = String(steps[index] || '')
  .replaceAll('{first_name}', person.first_name)
  .replaceAll('{display_name}', person.display_name);
if (!text.trim()) return [{ json: { action: 'done', user_id: person.user_id } }];
// Last line of defence against a double send: this exact message is already in the conversation.
if (alreadySaid(text)) return [{ json: { action: 'already_sent', user_id: person.user_id, display_name: person.display_name } }];
return [{ json: {
  action: 'send',
  step: index === 0 ? 'opening_message' : `follow_up_${index}`,
  user_id: person.user_id,
  display_name: person.display_name,
  chat_id: chatId,
  text,
} }];
